mapper.select:
SELECT t.id, t.content_id, t.content_type, t.content_title, t.content_description, t.category_section, t.author, COALESCE(c.application_module, '') as application_module, COALESCE(c.application_project, '') as application_project, COALESCE(c.channel, '') as channel, COALESCE(c.related_diseases, '') as related_disease, COALESCE(c.related_symptoms, '') as related_symptom, COALESCE(c.related_products, '') as related_product, COALESCE(c.is_pinned, 0) as pin_status, t.content_status, t.view_count, t.like_count, t.publish_time, t.article_url, t.created_at, t.updated_at FROM ( -- 图文素材 SELECT id, content_id, '文章' as content_type, content_title, article_description as content_description, category_section, author, content_status, view_count, like_count, publish_time, article_link as article_url, created_time as created_at, updated_time as updated_at FROM education_image_content
UNION ALL
-- 视频素材 SELECT id, video_id as content_id, '视频' as content_type, video_title as content_title, video_description as content_description, '' as category_section, author, content_status, view_count, like_count, publish_time, '' as article_url, created_at, updated_at FROM edu_video_asset ) t LEFT JOIN content_application_config c ON t.content_id = c.content_id AND t.content_type = c.content_type
AND t.content_title LIKE CONCAT('%', #{contentTitle}, '%')
AND t.author LIKE CONCAT('%', #{author}, '%')
AND t.content_type = #{resourceType}
AND t.category_section = #{categorySection}
AND t.content_status = #{status}
AND c.channel = #{channel}
AND c.is_pinned = 1
AND (c.is_pinned = 0 OR c.is_pinned IS NULL)
AND t.publish_time >= #{publishStartTime}
AND t.publish_time <= #{publishEndTime}
ORDER BY t.created_at DESC
